mapper.select:
select f.id, f.user_id AS userId, u.user_name AS userName, f.sn, f.home_latitude AS homeLatitude, f.home_longitude AS homeLongitude, f.start_time AS startTime, f.end_time AS endTime, f.duration, f.max_altitude AS maxAltitude, f.max_speed AS maxSpeed, f.distance, f.status, f.create_time AS createTime, f.modification_time AS modificationTime from flights f left join users u on f.user_id = u.user_id
and f.user_id = #{userId} and (f.sn like concat('%',#{keyword},'%') or u.user_name like concat('%',#{keyword},'%'))
order by f.start_time desc limit #{offset}, #{size}

select count(*) from flights f left join users u on f.user_id = u.user_id

    and f.user_id = #{userId}
    and (f.sn like concat('%',#{keyword},'%') or u.user_name like concat('%',#{keyword},'%'))
